-- БелЛот: новости на сайте — правятся в админке (06.10.2026). Повторный запуск безопасен. Те же определения — в schema.sql.
-- Робот при публикации берёт опубликованные новости в сайт; фото из админки (JPEG base64, уже уменьшено в браузере)
-- кладёт файлом news/<slug>.jpg. Фото по умолчанию — файлы сайта img/news/… (photo = путь).
create table if not exists news (
  slug text primary key,                       -- адрес статьи: #/news/<slug>
  date date not null default current_date,
  title text not null,
  lead text,                                   -- вступление: в карточке и под заголовком
  body text,                                   -- текст, абзацы через пустую строку
  photo text,                                  -- JPEG base64 из админки или путь к файлу сайта (img/news/…)
  src text, src_name text,                     -- источник
  cta_text text, cta_url text,                 -- кнопка под статьёй
  published boolean not null default true,
  updated_at timestamptz not null default now()
);
alter table news enable row level security;
drop policy if exists admin_all on news;
create policy admin_all on news for all using ((select is_admin())) with check ((select is_admin()));
-- три первые новости (06.10.2026)
insert into news (slug, date, title, lead, body, photo, src, src_name, cta_text, cta_url) values
($q$zemlya-minskij-rajon-16-oktyabrya$q$, $q$2026-09-19$q$::date, $q$16 октября — аукцион земли под Минском: участки от 11 до 225 тысяч рублей$q$, $q$Минский район выставляет восемь участков под жилой дом — от Ратомки и Колодищ до деревни Селище.$q$, $q$На 16 октября 2026 года назначен аукцион по продаже земельных участков в Минском районе. На торги выходят восемь участков — в агрогородках Ратомка и Колодищи, а также в деревнях Подгорье, Птичь, Селище и Василевщина.

Разброс стартовых цен большой. Самый дорогой лот — в Ратомке, его начальная цена 225 тысяч рублей. Самый доступный — в деревне Селище, за 11 тысяч рублей.

Стартовая цена на земельных аукционах под Минском — только начало: на востребованных участках ставки часто поднимаются в разы. Перед подачей заявки стоит сравнить лот с ценами на похожие участки и заранее определить для себя предел.$q$, $q$img/news/zemlya-minskij-rajon-16-oktyabrya.jpg$q$, $q$https://myfin.by/article/rynki/zemla-pod-minskom-ot-11-tysac-rublej-kakie-ucastki-vystavili-na-aukcion-48559$q$, $q$Myfin.by$q$, $q$Земельные участки на БелЛот$q$, $q$#/s/nedvizhimost?land=1$q$),
($q$pustuyushchie-doma-2-kvartal-2026$q$, $q$2026-07-08$q$::date, $q$Каждый второй пустующий дом в Беларуси продают за одну базовую$q$, $q$Итоги второго квартала: 357 сделок, 193 дома ушли по символической цене.$q$, $q$Национальное кадастровое агентство подвело итоги продажи пустующих домов за апрель–июнь 2026 года. Всего заключено 357 сделок: 140 домов продано через аукцион, 217 — без торгов.

Примерно каждый второй дом — 193 объекта — купили за одну базовую величину. Это возможно, когда на дом нет других желающих или аукцион не состоялся.

Больше всего сделок в Гродненской области — 96. Дальше Минская (64), Брестская (63), Витебская (57) и Могилёвская (56) области; в Гомельской — 21.

Такие дома часто требуют серьёзного ремонта, а покупатель обязан привести их в порядок в установленный срок. Перед покупкой стоит съездить на осмотр и оценить состояние дома и участка.$q$, $q$img/news/pustuyushchie-doma-2-kvartal-2026.jpg$q$, $q$https://myfin.by/article/rynki/kazdyj-vtoroj-pustuusij-dom-v-belarusi-prodaut-za-1-bazovuu-itogi-vtorogo-kvartala-2026-46811$q$, $q$Myfin.by$q$, $q$Недвижимость на торгах$q$, $q$#/s/nedvizhimost$q$),
($q$uchastok-leskovka-192-tysyachi$q$, $q$2026-06-19$q$::date, $q$Участок под Минском продали за 192 тысячи долларов — вдвое дороже стартовой цены$q$, $q$На аукционе в Минском районе цены на землю выросли в 2–3 раза от начальных.$q$, $q$В июне прошёл аукцион по продаже земельных участков под жилые дома в Минском и Березинском районах. Самыми дорогими стали два участка по 22 сотки в Лесковке: оба стартовали с 250 тысяч рублей и ушли примерно за 536 тысяч рублей — около 192 тысяч долларов. За них боролись пять и семь участников.

Ещё сильнее подорожал участок в Колодищах на 16 соток: при стартовой цене 150 тысяч рублей его продали за 475 тысяч, заявок было десять. Участок в Малиновке ушёл за 215 тысяч рублей при старте 150 тысяч.

Если у лота много желающих, итоговая цена может в разы превысить начальную. Поэтому стоит смотреть не только на стартовую цену, но и на итоги похожих торгов — они есть в архиве БелЛот.$q$, $q$img/news/uchastok-leskovka-192-tysyachi.jpg$q$, $q$https://nashaniva.com/ru/398035$q$, $q$Наша Ніва (по данным Realt)$q$, $q$Архив торгов с итогами$q$, $q$#/catalog?st=arch$q$)
on conflict (slug) do nothing;
-- «есть неопубликованные изменения» в админке учитывает и новости
do $$ begin
  if position('from news) x)' in pg_get_functiondef('public.admin_stats()'::regprocedure)) = 0 then
    execute replace(pg_get_functiondef('public.admin_stats()'::regprocedure), 'from lot_photos) x)', 'from lot_photos union all select max(updated_at) from news) x)');
  end if;
end $$;
